def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, cells))

    # The marker is the prominent long, straight component.
    def line_score(item):
        color, cells = item
        rs = {r for r, c in cells}
        cs = {c for r, c in cells}
        return len(cells) if len(rs) == 1 or len(cs) == 1 else 0

    marker_color, marker = max(comps, key=line_score)
    mr = min(r for r, c in marker)
    mx = max(r for r, c in marker)
    mc = min(c for r, c in marker)
    mxc = max(c for r, c in marker)

    # Recolor the object lying nearest the marker's open end.
    vertical = len({c for r, c in marker}) == 1
    if vertical:
        end = (mx, mc)
    else:
        end = (mr, mxc)

    choices = []
    for color, cells in comps:
        if cells is marker:
            continue
        dist = min(abs(r - end[0]) + abs(c - end[1]) for r, c in cells)
        choices.append((dist, color, cells))
    if not choices:
        return [row[:] for row in grid]

    _, _, target = min(choices, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = marker_color
    return out
